var s=`0936-chirashi-sushi`;var n=`world-0936`;var a=`JP`;var r=`east-asia`;var t=8;var o=64;var d={en:`Chirashi Sushi`,ua:`Чірасі-суші`};var h={en:`Chirashi Sushi is a Japan dish made with sushi rice, rice vinegar, shrimp, smoked salmon. This home-scale recipe assigns measured ingredients to the steps where they are used. Smoked salmon and cooked shrimp replace raw sashimi toppings.`,ua:`Чірасі-суші, страва кухні країни Японія. Основні складники: рис для суші, рисовий оцет, креветка, копчений лосось. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів. Копчений лосось і готові креветки замінюють сирі сашимі-начинки.`};var g=[{en:`Spread the rice evenly into the flavorful liquid. Cook uncovered or partly covered for about 24 minutes until the liquid is absorbed; do not over-stir.`,ua:`Рівномірно розподіліть рис у ароматній рідині. Готуйте приблизно 24 хвилин до вбирання рідини, не перемішуючи надмірно.`,t:[`rice-washing`,`absorption-cooking`],m:24,i:[[`sushi-rice`,440,`g`],[`water`,480,`ml`]]},{en:`Fold in the dressing ingredients, season to taste and serve, or chill briefly as appropriate.`,ua:`Обережно змішайте із заправкою, приправте до смаку й подавайте або трохи охолодіть за потреби.`,t:[`tossing`,`seasoning`],m:7,i:[[`rice-vinegar`,65,`ml`],[`white-granulated-sugar`,35,`g`],[`table-salt`,6,`g`]]},{en:`Poach the listed ingredients in barely simmering liquid for about 6 minutes until tender and cooked through.`,ua:`Пошируйте зазначені продукти в рідині без бурхливого кипіння приблизно 6 хвилин до готовності й м’якості.`,t:[`poaching`],m:6,i:[[`shrimp`,240,`g`]]},{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:15,i:[[`smoked-salmon`,220,`g`],[`cucumber`,180,`g`],[`avocado`,2,`pcs`]]},{en:`Arrange the prepared cooked components and listed toppings in a serving dish, keeping hot foods hot and chilled components cold until serving.`,ua:`Складіть готові приготовлені компоненти й зазначені додатки в посуді для подавання, підтримуючи гаряче гарячим, а холодне охолодженим.`,t:[`layered-assembly`,`garnishing`],m:9,i:[[`nori`,3,`pcs`],[`salmon-roe`,90,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`pickled-ginger`,40,`g`]]}];var l={slug:s,id:n,country:`JP`,region:r,servings:8,minutes:64,title:d,text:h,steps:g};export{a as country,l as default,n as id,o as minutes,r as region,t as servings,s as slug,g as steps,h as text,d as title};